// Open-Meteo'dan Istanbul'un anlik sicaklik ve ruzgar hizini isteyecek
// msg'yi hazirlar. Anahtar gerektirmeyen, herkese acik bir servis.
//
// Zamanlayici (saatte bir) ve elle tetikleme buraya gelir; yeniden deneme
// dongusu de (delay) buraya geri baglanir -- o yuzden deneme sayacini
// SIFIRLAMIYORUZ, sadece yoksa baslatiyoruz.

msg.kaynak = msg.kaynak || "zamanlayici";
msg.deneme = msg.deneme || 0;
msg.tetiklenme = msg.tetiklenme || new Date().toISOString();

msg.method = "GET";
msg.url = "https://api.open-meteo.com/v1/forecast" +
  "?latitude=41.0082&longitude=28.9784" +
  "&current=temperature_2m,wind_speed_10m" +
  "&timezone=Europe%2FIstanbul";
msg.requestTimeout = 20000;      // 20 sn icinde cevap yoksa hata -> catch
delete msg.headers;              // onceki bir HTTP yanitinin basliklari istege gitmesin
delete msg.payload;

node.status({ fill: "blue", shape: "dot", text: msg.kaynak + (msg.deneme ? " / deneme " + (msg.deneme + 1) : "") });
return msg;

// HTTP yanitini dogrular ve tek bir "okuma" kaydina cevirir.
//
// http request dugumu 4xx/5xx'te hata FIRLATMAZ, sadece statusCode koyar.
// Bu yuzden kontrolu biz yapiyoruz ve sorun varsa node.error(..., msg) ile
// catch'e gonderiyoruz -- akis sessizce olmesin (Ders 7).

const p = msg.payload;
const kod = msg.statusCode;

if (kod !== 200) {
  node.error("Hava servisi HTTP " + kod + " dondu", msg);
  return null;
}
if (!p || typeof p !== "object" || !p.current) {
  node.error("Hava servisi beklenmeyen yanit verdi (JSON degil ya da 'current' yok)", msg);
  return null;
}

const sicaklik = Number(p.current.temperature_2m);
const ruzgar = Number(p.current.wind_speed_10m);
if (!isFinite(sicaklik) || !isFinite(ruzgar)) {
  node.error("Hava servisi yanitinda sicaklik/ruzgar sayi degil", msg);
  return null;
}

msg.yeniKayit = {
  tip: "okuma",
  zaman: new Date().toISOString(),          // okumayi yaptigimiz an (UTC)
  olcumZamani: p.current.time,              // servisin olcum zamani (Istanbul saati)
  sicaklik: sicaklik,
  ruzgar: ruzgar,
  kaynak: msg.kaynak,
  deneme: (msg.deneme || 0) + 1
};

node.status({ fill: "green", shape: "dot", text: sicaklik + " C / " + ruzgar + " km/s" });
return msg;

// catch -> burasi. Servis cevap vermedi ya da bozuk cevap verdi.
//
// Cikis 1: yeniden dene (delay -> istek hazirla)
// Cikis 2: vazgec -> hatayi da kayda yaz (Excel'in "Hatalar" sayfasi)
//
// Sayac msg uzerinde (Ders 7.6): ayni anda gelen iki tetikleme birbirinin
// hakkini yemesin.

const ENUST_DENEME = 3;
const metin = (msg.error && msg.error.message) || String(msg.error || "bilinmeyen hata");
const gecici = /timeout|timed out|ETIMEDOUT|ECONNRESET|ECONNREFUSED|ENOTFOUND|EAI_AGAIN|socket hang up|HTTP 5\d\d|HTTP 429/i.test(metin);

msg.deneme = (msg.deneme || 0) + 1;

if (gecici && msg.deneme < ENUST_DENEME) {
  node.status({ fill: "yellow", shape: "ring", text: "deneme " + msg.deneme + "/" + ENUST_DENEME + ": " + metin.slice(0, 30) });
  node.warn("Hava servisi hatasi, yeniden denenecek (" + msg.deneme + "/" + ENUST_DENEME + "): " + metin);
  delete msg.error;
  return [msg, null];
}

msg.yeniKayit = {
  tip: "hata",
  zaman: new Date().toISOString(),
  mesaj: metin.slice(0, 300),
  gecici: gecici,
  deneme: msg.deneme,
  kaynak: msg.kaynak || "?"
};
delete msg.error;

node.status({ fill: "red", shape: "dot", text: "vazgecildi: " + metin.slice(0, 40) });
return [null, msg];

// "gecmisi oku" (file in) hata verdiyse buraya gelir. Ilk calismada dosya
// henuz yoktur -- bu bir hata degil, bos gecmistir.

const metin = (msg.error && msg.error.message) || "";
if (!/ENOENT|no such file/i.test(metin)) {
  node.warn("Gecmis dosyasi okunamadi, bos kabul ediliyor: " + metin);
}
delete msg.error;
msg.payload = "";
return msg;

// Gecmisi (JSONL, her satir bir kayit) okur, yeni kaydi ekler.
// Okumaysa bir ONCEKI okumaya gore farki hesaplar; |fark| > 3 C ise uyari.
//
// Neden JSONL + Excel'i her seferinde bastan uretmek: Excel'e "satir eklemek"
// icin dosyayi okuyup cozmek gerekir; JSONL'e eklemek tek satirdir ve bozulmaz.
// Gercek kayit JSONL'dir, Excel onun goruntusudur.
//
// Cikis 1 -> JSONL'e eklenecek satir (file, append)
// Cikis 2 -> tum kayitlar (Excel uretimi)

const ESIK = 3;   // derece

const kayitlar = [];
for (const satir of String(msg.payload || "").split(/\r?\n/)) {
  if (!satir.trim()) continue;
  try { kayitlar.push(JSON.parse(satir)); }
  catch (e) { node.warn("Bozuk gecmis satiri atlandi: " + satir.slice(0, 80)); }
}

const k = msg.yeniKayit;
if (!k) { node.error("yeniKayit yok", msg); return null; }

if (k.tip === "okuma") {
  const onceki = kayitlar.filter(x => x.tip === "okuma").pop();
  if (onceki) {
    k.onceki = onceki.sicaklik;
    k.fark = Math.round((k.sicaklik - onceki.sicaklik) * 10) / 10;
    k.uyari = Math.abs(k.fark) > ESIK;
  } else {
    k.onceki = null;
    k.fark = null;
    k.uyari = false;
  }
}
kayitlar.push(k);

const satirMsg = { filename: "/internal-storage-files/hava/okumalar.jsonl", payload: JSON.stringify(k) };

msg.kayitlar = kayitlar;
msg.payload = null;

const okumaSayisi = kayitlar.filter(x => x.tip === "okuma").length;
node.status(k.tip === "okuma"
  ? { fill: k.uyari ? "yellow" : "green", shape: "dot", text: "#" + okumaSayisi + " " + k.sicaklik + " C" + (k.fark !== null ? " (" + (k.fark > 0 ? "+" : "") + k.fark + ")" : "") + (k.uyari ? " UYARI" : "") }
  : { fill: "red", shape: "ring", text: "hata kaydedildi" });

return [satirMsg, msg];

// Tum kayitlardan dort sayfali Excel kurar (json-to-excel, Ders 10.1):
//   Okumalar  -- her okuma bir satir (en yeni en altta)
//   Uyarilar  -- onceki okumaya gore 3 C'den fazla degisim
//   Hatalar   -- servis cevap vermediginde
//   Ozet      -- kabul kriteri icin: otomatik satir sayisi vb.

const KIRMIZI = { fontColor: "9C0006", fill: "FFC7CE" };
const MAVI    = { fontColor: "1F4E79", fill: "DDEBF7" };
const BASLIK  = { bold: true };

function yerel(iso) {     // UTC ISO -> Istanbul saati, "01.10.2026 16:30"
  if (!iso) return "";
  try {
    return new Date(iso).toLocaleString("tr-TR", { timeZone: "Europe/Istanbul", day: "2-digit", month: "2-digit", year: "numeric", hour: "2-digit", minute: "2-digit" });
  } catch (e) { return iso; }
}

const kayitlar = msg.kayitlar || [];
const okumalar = kayitlar.filter(k => k.tip === "okuma");
const hatalar = kayitlar.filter(k => k.tip === "hata");

const okumaSayfasi = okumalar.map((k, i) => ({
  "No": i + 1,
  "Okuma zamani": yerel(k.zaman),
  "Olcum zamani (servis)": k.olcumZamani || "",
  "Sicaklik (C)": k.sicaklik,
  "Ruzgar (km/s)": k.ruzgar,
  "Fark (C)": k.fark === null || k.fark === undefined ? "" : (k.uyari ? { value: k.fark, style: KIRMIZI } : k.fark),
  "Kaynak": k.kaynak === "zamanlayici" ? "otomatik" : (k.kaynak || "")
}));

const uyariSayfasi = okumalar.filter(k => k.uyari).map(k => ({
  "Okuma zamani": yerel(k.zaman),
  "Onceki (C)": k.onceki,
  "Simdiki (C)": k.sicaklik,
  "Fark (C)": { value: k.fark, style: KIRMIZI },
  "Yon": k.fark > 0 ? "YUKSELIS" : "DUSUS",
  "Kaynak": k.kaynak === "zamanlayici" ? "otomatik" : (k.kaynak || "")
}));
if (uyariSayfasi.length === 0) uyariSayfasi.push({ "Okuma zamani": "Henuz 3 C'den buyuk degisim yok", "Onceki (C)": "", "Simdiki (C)": "", "Fark (C)": "", "Yon": "", "Kaynak": "" });

const hataSayfasi = hatalar.map(k => ({
  "Zaman": yerel(k.zaman),
  "Hata": k.mesaj,
  "Deneme": k.deneme,
  "Gecici mi": k.gecici ? "evet" : "hayir",
  "Kaynak": k.kaynak === "zamanlayici" ? "otomatik" : (k.kaynak || "")
}));
if (hataSayfasi.length === 0) hataSayfasi.push({ "Zaman": "Hata yok", "Hata": "", "Deneme": "", "Gecici mi": "", "Kaynak": "" });

const otomatik = okumalar.filter(k => k.kaynak === "zamanlayici").length;
const son = okumalar[okumalar.length - 1];
const ozet = [
  { "Bilgi": { value: "Otomatik okuma sayisi", style: BASLIK }, "Deger": otomatik >= 3 ? { value: otomatik, style: MAVI } : otomatik },
  { "Bilgi": { value: "Toplam okuma", style: BASLIK }, "Deger": okumalar.length },
  { "Bilgi": { value: "Uyari", style: BASLIK }, "Deger": okumalar.filter(k => k.uyari).length },
  { "Bilgi": { value: "Servis hatasi", style: BASLIK }, "Deger": hatalar.length },
  { "Bilgi": { value: "Son okuma", style: BASLIK }, "Deger": son ? yerel(son.zaman) + " -- " + son.sicaklik + " C, " + son.ruzgar + " km/s" : "-" },
  { "Bilgi": { value: "Zamanlayici", style: BASLIK }, "Deger": "saatte bir (3600 sn)" },
  { "Bilgi": { value: "Uyari esigi", style: BASLIK }, "Deger": "onceki okumaya gore 3 C'den fazla" }
];

msg.payload = { data: { "Okumalar": okumaSayfasi, "Uyarilar": uyariSayfasi, "Hatalar": hataSayfasi, "Ozet": ozet } };
msg.filename = "/internal-storage-files/hava/hava-nobetcisi.xlsx";

node.status({ fill: "blue", shape: "dot", text: okumalar.length + " okuma, " + otomatik + " otomatik" });
return msg;

// Hava Nobetcisi menusundeki dort sayfanin (Ozet / Okumalar / Uyarilar /
// Hatalar) acilisinda calisir. Excel'deki ayni adli sayfanin satirlarini
// uretir ve sayfadaki tabloya (datagrid, anahtari "tablo") basar.
//
// Hangi sayfa oldugu msg.hvSayfa'da (form'un onInit cikisindaki kucuk
// isaret dugumu koyar).
//
// view action "update" yaniti, msg.submission'daki alanlari forma doldurur:
// { tablo: [ {kolon: deger}, ... ] }   (aXet on yuz: initSubmission = response.submission)

const kayitlar = [];
for (const satir of String(msg.payload || "").split(/\r?\n/)) {
  if (!satir.trim()) continue;
  try { kayitlar.push(JSON.parse(satir)); } catch (e) {}
}

function yerel(iso) {
  if (!iso) return "";
  try { return new Date(iso).toLocaleString("tr-TR", { timeZone: "Europe/Istanbul", day: "2-digit", month: "2-digit", year: "numeric", hour: "2-digit", minute: "2-digit" }); }
  catch (e) { return iso; }
}
const isaretli = (f) => (f > 0 ? "+" : "") + f;
const kaynakAdi = (k) => k.kaynak === "zamanlayici" ? "otomatik" : (k.kaynak || "");
const S = (v) => (v === null || v === undefined) ? "" : String(v);

const okumalar = kayitlar.filter(k => k.tip === "okuma");
const hatalar = kayitlar.filter(k => k.tip === "hata");
const uyarilar = okumalar.filter(k => k.uyari);
const otomatik = okumalar.filter(k => k.kaynak === "zamanlayici").length;
const son = okumalar[okumalar.length - 1];

let tablo;
switch (msg.hvSayfa) {
  case "ozet":
    tablo = [
      { bilgi: "Otomatik okuma sayisi", deger: otomatik + (otomatik >= 3 ? "  (kabul kriteri en az 3: TAMAM)" : "  (kabul kriteri: en az 3)") },
      { bilgi: "Toplam okuma", deger: S(okumalar.length) },
      { bilgi: "Uyari", deger: S(uyarilar.length) },
      { bilgi: "Servis hatasi", deger: S(hatalar.length) },
      { bilgi: "Son okuma", deger: son ? yerel(son.zaman) + "  --  " + son.sicaklik + " C, " + son.ruzgar + " km/s" : "Henuz okuma yok" },
      { bilgi: "Zamanlayici", deger: "saatte bir (3600 sn)" },
      { bilgi: "Uyari esigi", deger: "onceki okumaya gore 3 C'den fazla" }
    ];
    break;

  case "okumalar":                                       // en yeni ustte
    tablo = okumalar.map((k, i) => ({
      no: S(i + 1), zaman: yerel(k.zaman), sicaklik: k.sicaklik + " C", ruzgar: k.ruzgar + " km/s",
      fark: k.fark === null || k.fark === undefined ? "-" : isaretli(k.fark) + " C" + (k.uyari ? "  UYARI" : ""),
      kaynak: kaynakAdi(k)
    })).reverse();
    if (!tablo.length) tablo = [{ no: "", zaman: "Henuz okuma yok", sicaklik: "", ruzgar: "", fark: "", kaynak: "" }];
    break;

  case "uyarilar":
    tablo = uyarilar.map(k => ({
      zaman: yerel(k.zaman), yon: k.fark > 0 ? "YUKSELIS" : "DUSUS",
      onceki: k.onceki + " C", simdiki: k.sicaklik + " C", fark: isaretli(k.fark) + " C", kaynak: kaynakAdi(k)
    })).reverse();
    if (!tablo.length) tablo = [{ zaman: "Henuz uyari yok (3 C'den buyuk degisim olmadi)", yon: "", onceki: "", simdiki: "", fark: "", kaynak: "" }];
    break;

  case "hatalar":
    tablo = hatalar.map(k => ({
      zaman: yerel(k.zaman), hata: S(k.mesaj), deneme: S(k.deneme),
      tur: k.gecici ? "gecici" : "kalici", kaynak: kaynakAdi(k)
    })).reverse();
    if (!tablo.length) tablo = [{ zaman: "Hata yok", hata: "", deneme: "", tur: "", kaynak: "" }];
    break;

  default:
    node.error("Bilinmeyen sayfa: " + msg.hvSayfa, msg);
    return null;
}

msg.submission = { tablo: tablo };
node.status({ fill: "blue", shape: "dot", text: msg.hvSayfa + ": " + tablo.length + " satir" });
return msg;

// "Excel'i indir" dugmesi: kalici klasordeki Excel'i (file in, Buffer)
// indirme baglantisina cevirir (ortak/indirme-bagi-olustur.js). Dosya yoksa catch -> 09-sayfa-hatasi.js.

msg.indirilecek = { data: msg.payload, ad: "hava-nobetcisi.xlsx" };   // -> ortak/indirme-bagi-olustur.js
msg.messages = { mesaj: "Excel hazir." };
node.status({ fill: "green", shape: "dot", text: Math.round(msg.payload.length / 1024) + " KB" });
return msg;

// Indirilecek dosya icin 10 dakika gecerli, tahmin edilemez bir baglanti uretir.
//
// Neden: aXet'in view action indirmesi tarayicida tipsiz bir Blob'u, sayfaya
// eklenmemis bir <a> ile tikliyor; Edge dosyayi ".tmp" olarak kaydedebiliyor.
// Bu yuzden dosyayi kendi HTTP ucumuzdan (indirme-sun.js) dogru basliklarla
// veriyoruz. Baglanti, Okta korumali bir form islemi sonunda uretildigi icin
// sadece giris yapmis kullanici gorur.
//
// Girdi : msg.indirilecek = { data: Buffer, ad: "dosya.xlsx" }
// Cikti : msg.messages.token / msg.messages.dosya  (view action mesajinda <%= %>)

const SURE_DK = 10;
const k = msg.indirilecek;
if (!k || !k.data) { node.error("indirilecek dosya yok", msg); return null; }

const depo = global.get("indirmeler") || {};
const simdi = Date.now();
for (const t of Object.keys(depo)) if (depo[t].bitis < simdi) delete depo[t];   // suresi dolanlari temizle

let token = "";
while (token.length < 32) token += Math.random().toString(36).slice(2);
token = token.slice(0, 32);

depo[token] = { data: k.data, ad: k.ad, bitis: simdi + SURE_DK * 60000 };
global.set("indirmeler", depo);

msg.messages = Object.assign({}, msg.messages, { token: token, dosya: k.ad, sure: String(SURE_DK) });
delete msg.indirilecek;
delete msg.downloadFileSubmission;     // aXet'in kendi (hatali) indirmesi devre disi

node.status({ fill: "green", shape: "dot", text: k.ad + " (" + Object.keys(depo).length + " bagli)" });
return msg;

// Sayfalardaki dosya okumalari hata verirse: en olasi sebep dosyanin henuz
// olusmamis olmasi. Formu bekletme, acikla.
// Cikis 1 -> sayfa acilisi view action'i, Cikis 2 -> "Excel'i indir" view action'i

const metin = (msg.error && msg.error.message) || "";
const yok = /ENOENT|no such file/i.test(metin);
delete msg.error;
delete msg.downloadFileSubmission;

if (msg.hvSayfa) {                                       // sayfa acilisi
  const aciklama = yok ? "Henuz okuma yok -- zamanlayici saatte bir calisir" : "Gecmis okunamadi: " + metin;
  const ilkKolon = { ozet: "bilgi", okumalar: "zaman", uyarilar: "zaman", hatalar: "zaman" }[msg.hvSayfa] || "zaman";
  const satir = {}; satir[ilkKolon] = aciklama;
  msg.submission = { tablo: [satir] };
  return [msg, null];
}
msg.messages = { mesaj: yok ? "Excel henuz olusmadi; ilk okumadan sonra indirilebilir." : "Excel okunamadi: " + metin };
return [null, msg];
